from decimal import Decimal
from datetime import datetime
import re

def clean(record, key):
    value = record.get(key)
    if value is None:
        return ""
    if not isinstance(value, str):
        raise TypeError("Fields must be strings or None")
    return value.strip()

def amount_cents(text):
    if not text:
        return None
    if not re.fullmatch(r"[+-]?\d+(?:\.\d{1,2})?", text):
        raise ValueError("Invalid amount")
    return int(Decimal(text) * 100)

def day(text):
    if not text:
        return None
    for pattern, fmt in ((r"\d{4}-\d{2}-\d{2}", "%Y-%m-%d"),
                         (r"\d{2}/\d{2}/\d{4}", "%d/%m/%Y")):
        if re.fullmatch(pattern, text):
            return datetime.strptime(text, fmt).date().isoformat()
    raise ValueError("Invalid date")

def normalize_record(record):
    if not isinstance(record, dict):
        raise TypeError("Record must be a dict")
    return {"name": clean(record, "name"),
            "amount_cents": amount_cents(clean(record, "amount")),
            "day": clean(record, "date") or None}

